edits.newText:
@keyframes scoop {
  0%, 100% { transform: var(--release); }
  18% { transform: var(--follow-through); }
  50% { transform: var(--ready); }
  70% { transform: var(--catch); }
  82% { transform: var(--dip); }
}

/* The two flights have constant horizontal speed and an eased rise and fall. */
@keyframes cross-stage {
  0%, 100% { transform: translateX(608px); }
  40% { transform: translateX(698px); animation-timing-function: ease-in-out; }
  44% { transform: translateX(681px); animation-timing-function: ease-in-out; }
  50% { transform: translateX(630px); }
  90% { transform: translateX(562px); animation-timing-function: ease-in-out; }
  94% { transform: translateX(577px); animation-timing-function: ease-in-out; }
}

edits.oldText:
@keyframes scoop {
  0%, 100% { transform: matrix(1, 0, 0, 1, 0, 0); }
  18% { transform: var(--follow-through); }
  50% { transform: var(--ready); }
  70% { transform: var(--catch); }
  82% { transform: var(--dip); }
}

/* The two flights have constant horizontal speed and an eased rise and fall. */
@keyframes cross-stage {
  0%, 100% { transform: translateX(585px); }
  40% { transform: translateX(682px); animation-timing-function: ease-in-out; }
  44% { transform: translateX(671px); animation-timing-function: ease-in-out; }
  50% { transform: translateX(645px); }
  90% { transform: translateX(560px); animation-timing-function: ease-in-out; }
  94% { transform: translateX(568px); animation-timing-function: ease-in-out; }
}

edits.newText:
@keyframes bottle-flip {
  0%, 76%, 100% { transform: rotate(0deg); }
  9%, 58.5% { transform: rotate(180deg); }
  27%, 50% { transform: rotate(360deg); }
}

